// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { addProductToCart, selectProductQuantity, submitCartQuantityUpdate } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(65000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/product/OLJCESPC7Z`);
    await addProductToCart(page);
    await page.goto(`${baseUrl}/product/66VCHSJNUP`);
    await selectProductQuantity(page, "2");
    await addProductToCart(page);
    await expect(page.getByTestId("cart-heading")).toContainText("Cart (3)");

    // Exercise the new POST /cart/update handler through the page's session cookie.
    // updateCartHandler empties the whole cart and re-inserts every line, so a second
    // line item must survive an update targeting a different product.
    const updateResponse = await submitCartQuantityUpdate(page, "OLJCESPC7Z", "4");
    expect(updateResponse.status()).toBe(302);
    expect(updateResponse.headers()["location"]).toBe("/cart");

    await page.goto(`${baseUrl}/cart`);
    await expect(page.getByTestId("cart-heading")).toContainText("Cart (6)");

    // Both line items must still be rendered, with the untouched line keeping quantity 2.
    await expect(page.getByRole("heading", { name: "Sunglasses", level: 4 })).toBeVisible();
    await expect(page.getByRole("heading", { name: "Tank Top", level: 4 })).toBeVisible();

    const qtyInputs = page.locator(".qty-control input.qty-input");
    await expect(qtyInputs).toHaveCount(2);
    await expect(qtyInputs.nth(0)).toHaveValue("4");
    await expect(qtyInputs.nth(1)).toHaveValue("2");
});
